CREATE TABLE "c_Booking" ("id" BIGINT NOT NULL, "a_Booking_booked_at" TIMESTAMP NOT NULL, "a_Booking_status" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_ItineraryItem" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_FlightSegment_flight_no" TEXT, "a_HotelStay_hotel_name" TEXT, "a_ItineraryItem_start_time" TIMESTAMP, "r_BookingItems_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('FlightSegment','HotelStay','ItineraryItem')), CHECK ((dtype IN ('FlightSegment')) OR "a_FlightSegment_flight_no" IS NULL), CHECK (NOT (dtype IN ('FlightSegment')) OR "a_FlightSegment_flight_no" IS NOT NULL), CHECK ((dtype IN ('HotelStay')) OR "a_HotelStay_hotel_name" IS NULL), CHECK (NOT (dtype IN ('HotelStay')) OR "a_HotelStay_hotel_name" IS NOT NULL), CHECK ((dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "a_ItineraryItem_start_time" IS NULL), CHECK (NOT (dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "a_ItineraryItem_start_time" IS NOT NULL), CHECK ((dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "r_BookingItems_source_id" IS NULL), CHECK (NOT (dtype IN ('FlightSegment','HotelStay','ItineraryItem')) OR "r_BookingItems_source_id" IS NOT NULL));
CREATE TABLE "c_Payment" ("id" BIGINT NOT NULL, "a_Payment_amount" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Traveler" ("id" BIGINT NOT NULL, "a_Traveler_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_BookingPayments" ("r_BookingPayments_source_id" BIGINT NOT NULL, "r_BookingPayments_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_BookingPayments_source_id", "r_BookingPayments_target_id"), UNIQUE ("r_BookingPayments_target_id"));
CREATE TABLE "l_TravelerBookings" ("r_TravelerBookings_source_id" BIGINT NOT NULL, "r_TravelerBookings_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_TravelerBookings_source_id", "r_TravelerBookings_target_id"), UNIQUE ("r_TravelerBookings_target_id"));
ALTER TABLE "c_ItineraryItem" ADD CONSTRAINT "fk_c_ItineraryItem_0" FOREIGN KEY ("r_BookingItems_source_id") REFERENCES "c_Booking" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_BookingPayments" ADD CONSTRAINT "fk_l_BookingPayments_0" FOREIGN KEY ("r_BookingPayments_source_id") REFERENCES "c_Booking" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_BookingPayments" ADD CONSTRAINT "fk_l_BookingPayments_1" FOREIGN KEY ("r_BookingPayments_target_id") REFERENCES "c_Payment" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_TravelerBookings" ADD CONSTRAINT "fk_l_TravelerBookings_0" FOREIGN KEY ("r_TravelerBookings_source_id") REFERENCES "c_Traveler" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_TravelerBookings" ADD CONSTRAINT "fk_l_TravelerBookings_1" FOREIGN KEY ("r_TravelerBookings_target_id") REFERENCES "c_Booking" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_BookingPayments"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Payment" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_BookingPayments" l WHERE l."r_BookingPayments_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: BookingPayments'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_BookingPayments_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Payment" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_BookingPayments"();
CREATE CONSTRAINT TRIGGER "ct_BookingPayments_link" AFTER INSERT OR UPDATE OR DELETE ON "l_BookingPayments" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_BookingPayments"();
CREATE FUNCTION "require_TravelerBookings"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Booking" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_TravelerBookings" l WHERE l."r_TravelerBookings_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: TravelerBookings'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_TravelerBookings_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Booking" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_TravelerBookings"();
CREATE CONSTRAINT TRIGGER "ct_TravelerBookings_link" AFTER INSERT OR UPDATE OR DELETE ON "l_TravelerBookings" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_TravelerBookings"();